27	const TOOL_ATTRIBUTE_KEYS = [
28	  'tool.name',
29	  'tool_name',
30	  'tool',
31	  'function.name',
32	  'function_name',
33	  'gen_ai.tool.name',
34	  'codex.mcp.tool',
35	  'agent.tool',
36	  'agent.tool_name',
37	  'agent.toolName',
38	] as const;
